window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e4fa5aaa14755d77"]={"versions": [{"id": "FIG-e4fa5aaa14755d77", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Feature-Modell / Feature-Baum nach FODA-Notation (<em>Feature-Oriented Domain Analysis</em>) gemäß AUTOSAR Foundation (<code>AUTOSAR_FO_TR_Features</code>, R24-11).</li>\n<li><strong>Architektur-Kontext:</strong> Plattformübergreifende funktionale Dekomposition auf Gesamtfahrzeugebene. Es definiert die Feature-Abhängigkeiten für softwarebasierte Fahrzeugaktualisierungen (OTA und Werkstatt-Flashverfahren) über Classic Platform (CP) und Adaptive Platform (AP) hinweg.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten:</strong></li>\n<li><code>FO_TR_FEAT_00223</code> (<code>Vehicle_Software_Update</code>): Übergeordnetes Root-/Compound-Feature für die ganzheitliche Software-Aktualisierung im E/E-Fahrzeugnetzwerk.</li>\n<li><code>FO_TR_FEAT_00224</code> (<code>Update_Orchestration</code>): Untergeordnetes Sub-Feature zur zentralen Ablaufsteuerung, Reihenfolgekoordination und Abhängigkeitsauflösung von Softwareständen.</li>\n<li><strong>Beziehungen & Semantik:</strong></li>\n<li><strong>Verbindung:</strong> Durchgezogene Kante mit ausgefülltem Kreis (<em>solid circle / bullet</em>) am Sub-Feature.</li>\n<li><strong>Kardinalität/Kopplung:</strong> <em>Mandatory Feature</em> ($1..1$). Wird das Feature <code>FO_TR_FEAT_00223</code> in einer Fahrzeugarchitektur beansprucht oder umgesetzt, ist <code>FO_TR_FEAT_00224</code> zwingend verpflichtend zu realisieren (keine optionale Dekomposition).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<p class=\"fig-p\">Das Diagramm selbst ist eine statische Feature-Dekomposition ohne Laufzeit-Semantik. Die daraus resultierende dynamische Ablaufkette der Orchestrierung umfasst:</p>\n<ol class=\"fig-list\">\n<li><strong>Pre-Condition & Safety Check:</strong> Validierung des Gesamtfahrzeugzustands (z. B. Parkposition, Ladezustand 12V/HV-Batterie) über das <em>State Management</em>.</li>\n<li><strong>Transfer & Kampagnen-Koordination:</strong> Verteilung der Softwarepakete an Zielinstanzen (AP-Knoten via UCM, CP-Knoten via Flash-Bootloader/UDS).</li>\n<li><strong>Phasen-Synchronisation:</strong> Entkoppelte Vorbereitung (<em>Process / Transfer</em>) mit nachgelagert synchronisiertem Aktivierungsbefehl (<em>Activate</em>) über alle Ziel-ECUs.</li>\n<li><strong>Verifikation & Fallback:</strong> Validierung der Gesamtintegrität nach Aktivierung; bei Scheitern Auslösen eines koordinierten Gesamtsystem-Rollbacks.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Adaptive Platform (AP):</strong> Determiniert die Implementierung eines <em>Vehicle Update and Configuration Management</em> (Vehicle UCM / VUCM) bzw. die Koordination via <code>ara::ucm</code> gemäß <code>AUTOSAR_AP_SWS_UpdateAndConfigurationManagement</code>.</li>\n<li><strong>Classic Platform (CP):</strong> Bedingt die Einbindung von CP-Knoten als Update-Targets, typischerweise gesteuert über den Diagnose-Stack (<code>Dcm</code> / UDS-Routinen ISO 14229-1) oder dedizierte OTA-Client-SWCs.</li>\n<li><strong>Konsequenzen für Systemarchitekten & Integratoren:</strong></li>\n<li>Ein softwaregestütztes Gesamtfahrzeug-Update darf architektonisch nicht als Ansammlung isolierter Steuergeräte-Flashes implementiert werden.</li>\n<li>Die Orchestrierungsinstanz muss Inter-ECU-Abhängigkeiten (Kompatibilitätsmatrizen, Kommunikationsmatrix-Versionen) validieren, bevor Schreib- oder Aktivierungsphasen freigegeben werden.</li>\n<li>Fehlertoleranz und Safe-State-Mechanismen müssen fahrzeugweit synchronisiert sein, um inkonsistente Zwischenzustände („bricked vehicle“) auszuschließen.</li>\n</ul>"}, {"id": "FIG-e1b87804b540e828", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Feature-Modell / Feature-Baum nach FODA-Notation (<em>Feature-Oriented Domain Analysis</em>) gemäß AUTOSAR Foundation (<code>AUTOSAR_FO_TR_Features</code>, R24-11).</li>\n<li><strong>Architektur-Kontext:</strong> Plattformübergreifende funktionale Dekomposition auf Gesamtfahrzeugebene. Es definiert die Feature-Abhängigkeiten für softwarebasierte Fahrzeugaktualisierungen (OTA und Werkstatt-Flashverfahren) über Classic Platform (CP) und Adaptive Platform (AP) hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten:</strong></li>\n<li><code>FO_TR_FEAT_00223</code> (<code>Vehicle_Software_Update</code>): Übergeordnetes Root-/Compound-Feature für die ganzheitliche Software-Aktualisierung im E/E-Fahrzeugnetzwerk.</li>\n<li><code>FO_TR_FEAT_00224</code> (<code>Update_Orchestration</code>): Untergeordnetes Sub-Feature zur zentralen Ablaufsteuerung, Reihenfolgekoordination und Abhängigkeitsauflösung von Softwareständen.</li>\n<li><strong>Beziehungen & Semantik:</strong></li>\n<li><strong>Verbindung:</strong> Durchgezogene Kante mit ausgefülltem Kreis (<em>solid circle / bullet</em>) am Sub-Feature.</li>\n<li><strong>Kardinalität/Kopplung:</strong> <em>Mandatory Feature</em> ($1..1$). Wird das Feature <code>FO_TR_FEAT_00223</code> in einer Fahrzeugarchitektur beansprucht oder umgesetzt, ist <code>FO_TR_FEAT_00224</code> zwingend verpflichtend zu realisieren (keine optionale Dekomposition).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm selbst ist eine statische Feature-Dekomposition ohne Laufzeit-Semantik. Die daraus resultierende dynamische Ablaufkette der Orchestrierung umfasst:</p>\n<ol class=\"fig-list\">\n<li><strong>Pre-Condition & Safety Check:</strong> Validierung des Gesamtfahrzeugzustands (z. B. Parkposition, Ladezustand 12V/HV-Batterie) über das <em>State Management</em>.</li>\n<li><strong>Transfer & Kampagnen-Koordination:</strong> Verteilung der Softwarepakete an Zielinstanzen (AP-Knoten via UCM, CP-Knoten via Flash-Bootloader/UDS).</li>\n<li><strong>Phasen-Synchronisation:</strong> Entkoppelte Vorbereitung (<em>Process / Transfer</em>) mit nachgelagert synchronisiertem Aktivierungsbefehl (<em>Activate</em>) über alle Ziel-ECUs.</li>\n<li><strong>Verifikation & Fallback:</strong> Validierung der Gesamtintegrität nach Aktivierung; bei Scheitern Auslösen eines koordinierten Gesamtsystem-Rollbacks.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Adaptive Platform (AP):</strong> Determiniert die Implementierung eines <em>Vehicle Update and Configuration Management</em> (Vehicle UCM / VUCM) bzw. die Koordination via <code>ara::ucm</code> gemäß <code>AUTOSAR_AP_SWS_UpdateAndConfigurationManagement</code>.</li>\n<li><strong>Classic Platform (CP):</strong> Bedingt die Einbindung von CP-Knoten als Update-Targets, typischerweise gesteuert über den Diagnose-Stack (<code>Dcm</code> / UDS-Routinen ISO 14229-1) oder dedizierte OTA-Client-SWCs.</li>\n<li><strong>Konsequenzen für Systemarchitekten & Integratoren:</strong></li>\n<li>Ein softwaregestütztes Gesamtfahrzeug-Update darf architektonisch nicht als Ansammlung isolierter Steuergeräte-Flashes implementiert werden.</li>\n<li>Die Orchestrierungsinstanz muss Inter-ECU-Abhängigkeiten (Kompatibilitätsmatrizen, Kommunikationsmatrix-Versionen) validieren, bevor Schreib- oder Aktivierungsphasen freigegeben werden.</li>\n<li>Fehlertoleranz und Safe-State-Mechanismen müssen fahrzeugweit synchronisiert sein, um inkonsistente Zwischenzustände („bricked vehicle“) auszuschließen.</li>\n</ul>"}], "trans": [{"from": "FIG-e4fa5aaa14755d77", "to": "FIG-e1b87804b540e828", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
